import {
  View,
  Text,
  StyleSheet,
  SafeAreaView,
  TouchableOpacity,
  useWindowDimensions,
  Platform,
  StatusBar,
} from 'react-native';

interface ResponsiveHeaderProps {
  title: string;
  leftAction?: {
    icon: string;
    onPress: () => void;
  };
  rightAction?: {
    icon: string;
    onPress: () => void;
  };
}

export function ResponsiveHeader({
  title,
  leftAction,
  rightAction,
}: ResponsiveHeaderProps) {
  const { width } = useWindowDimensions();
  const isTablet = width >= 768;

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar
        barStyle="light-content"
        backgroundColor="#0066cc"
        translucent={Platform.OS === 'android'}
      />

      <View style={styles.header}>
        <View style={styles.headerContent}>
          {/* LEFT */}
          <View style={styles.headerLeft}>
            {leftAction && (
              <TouchableOpacity onPress={leftAction.onPress}>
                <Text style={styles.headerIcon}>{leftAction.icon}</Text>
              </TouchableOpacity>
            )}
          </View>

          {/* CENTER */}
          <View style={styles.headerCenter}>
            <Text
              style={[
                styles.headerTitle,
                isTablet && styles.headerTitleTablet,
              ]}
              numberOfLines={1}
            >
              {title}
            </Text>
          </View>

          {/* RIGHT */}
          <View style={styles.headerRight}>
            {rightAction && (
              <TouchableOpacity onPress={rightAction.onPress}>
                <Text style={styles.headerIcon}>{rightAction.icon}</Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safeArea: {
    backgroundColor: '#0066cc',
  },
  header: {
    backgroundColor: '#0066cc',
    elevation: 4,
    height: 56,
  },
  headerContent: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 8,
  },
  headerLeft: {
    width: 48,
    alignItems: 'flex-start',
  },
  headerCenter: {
    flex: 1,
    alignItems: 'center',
  },
  headerRight: {
    width: 48,
    alignItems: 'flex-end',
  },
  headerIcon: {
    fontSize: 20,
    color: '#fff',
  },
  headerTitle: {
    fontSize: 18,
    fontWeight: '600',
    color: '#fff',
  },
  headerTitleTablet: {
    fontSize: 22,
  },
});
